  { id: 13, name: "C#" },
  { id: 14, name: "Haskell" },
  { id: 15, name: "Elixir" },
  { id: 16, name: "Erlang" },
  { id: 17, name: "Perl" },
  { id: 18, name: "PHP" },
  { id: 19, name: "Swift" },
  { id: 20, name: "Dart" }
];

export const onGet: RequestHandler = async (ev) => {
  const q = ev.query.get('q');
  const trimmed = q ? q.trim() : '';

  if (trimmed.length < 2) {
    return ev.json(400, { error: "query must be at least 2 characters" });
  }

  if (trimmed.length > 50) {
    return ev.json(400, { error: "query must be at most 50 characters" });
  }

  const len = trimmed.length;
  const delayMs = Math.max(120, 1600 - (len - 2) * 500);
  await new Promise((resolve) => setTimeout(resolve, delayMs));

  if (trimmed.toLowerCase() === 'boom') {
    return ev.json(500, { error: "internal server error" });
  }

  const results = dataset.filter(item =>
    item.name.toLowerCase().includes(trimmed.toLowerCase())
  );

  return ev.json(200, {
    query: trimmed,
    count: results.length,
    results
  });
};

